import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

const specPath = "week2/generated/day5-one-long-test.spec.ts";

await writeProjectFile(specPath, `// Week 2, Day 5 — one test doing five things: login, view history, pay
// bills, check billing history, log out. The waitForTimeout()s stand in for
// realistic per-step latency (a slower network, a heavier page) — they are
// not needed for correctness, only to make the accumulating cost visible.
import { test, expect } from "@playwright/test";
import { loginAs } from "../../_shared/test-helpers";

test("one long journey: login, view history, pay bills, check billing history, log out", async ({ page }) => {
  await loginAs(page);
  await expect(page.getByText("Leela")).toBeVisible();

  await page.getByText("Transaction History", { exact: true }).click();
  await page.waitForURL("**/accountDashboard");
  await page.waitForTimeout(6000);

  await page.goto("/dashboard");
  await page.getByText("Pay Bills", { exact: true }).click();
  await page.waitForURL("**/paymentDashboard");
  await page.waitForTimeout(6000);

  await page.goto("/dashboard");
  await page.getByText("Billing History", { exact: true }).click();
  await page.waitForTimeout(6000);

  await page.goto("/dashboard");
  await page.getByRole("button", { name: "LogOut" }).click();
  await page.waitForURL("**/login");
});
`.trim());

await runSpec(specPath);

// writeProjectFile and runSpec are already in scope from Example 1's cell —
// Deno's kernel shares one module scope across every cell in this notebook,
// so importing them again here would throw "already declared".
const specPath2 = "week2/generated/day5-split-isolation.spec.ts";

await writeProjectFile(specPath2, `// Week 2, Day 5 — the same journey, split by concern the way "one long test"
// invites. test 2 assumes test 1 already logged in. It hasn't — every test
// gets its own fresh page — so this is expected to fail. Run it and read the
// real error; that failure IS the lesson.
import { test, expect } from "@playwright/test";
import { loginAs } from "../../_shared/test-helpers";

test.describe("Dashboard journey, split into small tests", () => {
  test("test 1: log in", async ({ page }) => {
    await loginAs(page);
    await expect(page.getByText("Leela")).toBeVisible();
  });

  test("test 2: read the signed-in user's name", async ({ page }) => {
    // No loginAs() here — this test assumes test 1 already signed in.
    await page.goto("/dashboard");
    await expect(page.getByText("Leela")).toBeVisible();
  });
});
`.trim());

await runSpec(specPath2);

import { writeProjectFile, runSpec } from "../_shared/deno-helpers.ts";

const specPath = "week2/generated/day5-shared-context-preview.spec.ts";

await writeProjectFile(specPath, `// Week 2, Day 5 — PREVIEW ONLY. This is the shape of the fix (a context
// shared across dependent tests via beforeAll/afterAll), shown running for
// real so you know it genuinely works — not fully explained here. The real
// treatment of hooks, page vs browser scope, and test.describe is
// week3/day2_1.ipynb and week3/day2_2.ipynb.
import { test, expect, type Browser, type BrowserContext, type Page } from "@playwright/test";
import { loginAs } from "../../_shared/test-helpers";

test.describe("Dashboard journey, sharing one login via a shared context", () => {
  test.describe.configure({ mode: "serial" });

  let context: BrowserContext;
  let page: Page;

  test.beforeAll(async ({ browser }: { browser: Browser }) => {
    context = await browser.newContext();
    page = await context.newPage();
    await loginAs(page);
  });

  test.afterAll(async () => {
    await context.close();
  });

  test("test 1: log in", async () => {
    await expect(page.getByText("Leela")).toBeVisible();
  });

  test("test 2: read the signed-in user's name", async () => {
    // Same page object as test 1 — still sitting on /dashboard, still signed in.
    // No page.goto() here: this app keeps its session in memory only, so a full
    // navigation would reload the page and wipe it, context or no context.
    await expect(page.getByText("Leela")).toBeVisible();
  });
});
`.trim());

await runSpec(specPath);

